import{_ as i,l as d,o as e,c as r,v as o,p as c,x as t,d as n,i as s,S as T}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"LTO","description":"","frontmatter":{"title":"LTO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lto.md","filePath":"cs/lto.md","lastUpdated":1789023840000}'),p={name:"cs/lto.md"};function h(L,a,O,_,u,E){const l=d("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="lto" tabindex="-1">LTO <a class="header-anchor" href="#lto" aria-label="Permalink to &quot;LTO&quot;">​</a></h1><div class="epigraph"><p>链接期优化把多个编译单元的 IR 放到一起，得到全程序调用图与内联，而不要求源文件合成一份翻译单元。</p><footer>—— 据 Glek and Hubička, Optimizing real-world applications with GCC LTO；LLVM LTO/ThinLTO；龙书过程间优化整理</footer></div><p>上一课<a href="/cs/pgo">PGO</a>给热度，但单 TU 看不见其它 <code>.c</code> 的函数体。缺口是 <strong>LTO</strong>：编译器吐 IR 位码，链接器调优化器再代码生成。ThinLTO：摘要先行、并行后端，减内存。本课钉工作流，不写 ELF 节布局——链接课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 的分别编译使 <code>static</code> 小函数跨文件无法内联，虚调用目标不全。LTO：全程序（或近全）IR。缺口是<strong>何时优化、谁当链接器插件</strong>，不是 PGO 插桩。</p><p>代价：内存、时间、增量编译失效。ThinLTO 用函数摘要+导入热 callee 近似全 LTO。</p><h3 id="lto-不是「把-c-都-include-在一起」" tabindex="-1">LTO 不是「把 .c 都 <code>#include</code> 在一起」 <a class="header-anchor" href="#lto-不是「把-c-都-include-在一起」" aria-label="Permalink to &quot;LTO 不是「把 .c 都 `#include` 在一起」&quot;">​</a></h3><p>语言规则仍按 TU 看名字内部链接；LTO 在 IR 级合并。宏与 <code>static</code> 的身份按符号，不是文本粘贴。</p><p><span class="marginnote">GCC LTO。LLVM gold/lld 插件。ThinLTO（Johnson et al.）。本课不写 fat LTO 对象的全部格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>clang -flto</code>：<code>.o</code> 里是 bitcode。<code>lld</code> 调 <code>lto</code>：合并、内联、IPSCCP、DCE 无用全局、再分发后端。与 PGO：先 LTO 插桩或 IR 级轮廓。</p>',11)),(e(),c(T,null,{default:t(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TU%5B%22%E5%90%84%20TU%20%E2%86%92%20IR%22%5D%20--%3E%20LINK%5B%22%E9%93%BE%E6%8E%A5%E5%99%A8%E6%8F%92%E4%BB%B6%22%5D%0A%20%20LINK%20--%3E%20IPO%5B%22%E5%85%A8%E7%A8%8B%E5%BA%8F%E4%BC%98%E5%8C%96%22%5D%0A%20%20IPO%20--%3E%20CG%5B%22%E4%BB%A3%E7%A0%81%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/interprocedural-callgraph">调用图</a>：LTO 才有闭世界（静态链接）。动态库边界仍开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>符号可见性：被其它 <code>.so</code> 用的符号不能删、不能改约定。<code>hidden</code>/<code>internal</code> 使 DCE 更狠。不要 LTO 进不兼容的 IR 版本。</p><p>并行：ThinLTO 两阶段，摘要全局，优化仍分片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接脚本。后课默认：跨 TU 内联与 DCE 靠 LTO。下一课 UB：全程序分析更敢删「不可能」路径，风险也更大。</p><p>也不把 LTO 当 Java 的 JIT 全程序（那是运行时）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LTO：链接时优化 IR，补全程序视野。</li><li>ThinLTO 用摘要换可扩展性。</li><li>可见性与 <code>.so</code> 边界限制闭世界。</li><li>出处：Glek and Hubička；LLVM LTO/ThinLTO；对照龙书 IPO。</li></ul>',9))])}const P=i(p,[["render",h]]);export{f as __pageData,P as default};
